import { SwiperContainer } from "swiper/element";

class ImageTextBlocks extends HTMLElement {
  connectedCallback(): void {
    // Overlay toggle for plus/close buttons
    this.addEventListener("click", this.handleOverlayToggle);

    // Swiper navigation setup
    this.setupSwipers();
    this.setupDesktopNavigation();
  }

  disconnectedCallback(): void {
    this.removeEventListener("click", this.handleOverlayToggle);
  }

  private handleOverlayToggle = (event: Event): void => {
    const target = event.target as HTMLElement;

    const plusButton = target.closest(
      ".image-text-block__plus",
    ) as HTMLElement | null;
    const closeButton = target.closest(
      ".image-text-block__close",
    ) as HTMLElement | null;

    if (!plusButton && !closeButton) return;

    const blockWrapper = (plusButton || closeButton)?.closest(
      ".image-text-block--over_image",
    ) as HTMLElement | null;

    if (!blockWrapper) return;

    if (plusButton) {
      blockWrapper.classList.add("is-open");
    } else {
      blockWrapper.classList.remove("is-open");
    }
  };

  // ---------------- Swiper helpers -----------------

  private setupSwipers(): void {
    const swipers = this.querySelectorAll("swiper-container");

    swipers.forEach((swiperEl) => {
      // Skip swiper if currently hidden (e.g., mobile/desktop toggle)
      const element = swiperEl as HTMLElement;
      if (getComputedStyle(element).display === "none") return;

      // Initialise if rendered with init="false"
      const sc = swiperEl as SwiperContainer & { initialize?: () => void };
      if (!sc.swiper && sc.initialize) {
        sc.initialize();
      }

      const initialize = () => {
        this.setupSwiperNavigation(swiperEl as SwiperContainer);
      };

      // Wait until swiper element is initialised
      swiperEl.addEventListener("swiperinit", initialize);

      // If already initialised (hydrated server-side)
      if ((swiperEl as SwiperContainer).swiper) {
        initialize();
      }
    });
  }

  private setupSwiperNavigation(swiperEl: SwiperContainer): void {
    if (!swiperEl.swiper) return;

    const sectionId = this.getAttribute("data-section-id") || this.id;

    const nextButton =
      this.querySelector(`#swiper-button-next-${sectionId}`) ||
      this.querySelector(".swiper-button-next");
    const prevButton =
      this.querySelector(`#swiper-button-prev-${sectionId}`) ||
      this.querySelector(".swiper-button-prev");

    this.attachNavigationListeners(nextButton, prevButton, swiperEl);
  }

  private attachNavigationListeners(
    nextButton: Element | null,
    prevButton: Element | null,
    swiperEl: SwiperContainer,
  ): void {
    if (nextButton) {
      nextButton.addEventListener("click", (e: Event) => {
        e.preventDefault();
        e.stopPropagation();
        swiperEl.swiper.slideNext();
      });
    }

    if (prevButton) {
      prevButton.addEventListener("click", (e: Event) => {
        e.preventDefault();
        e.stopPropagation();
        swiperEl.swiper.slidePrev();
      });
    }
  }

  private setupDesktopNavigation(): void {
    const nextButton = this.querySelector(
      ".hide-on-mobile .swiper-button-next, .title-with-nav .swiper-button-next",
    );
    const prevButton = this.querySelector(
      ".hide-on-mobile .swiper-button-prev, .title-with-nav .swiper-button-prev",
    );

    // Find the first swiper in component for desktop nav
    const swiperEl = this.querySelector(
      "swiper-container",
    ) as SwiperContainer | null;

    if (!swiperEl) return;

    this.attachNavigationListeners(nextButton, prevButton, swiperEl);
  }
}

customElements.define("uwp-image-text-blocks", ImageTextBlocks);

export { ImageTextBlocks };
